"""Keep existing workspace connections readable across the cryptography upgrade."""
from src.stackwise.security import unseal


def test_fernet_token_from_cryptography_46_remains_readable(monkeypatch):
    # Public synthetic key and token generated by cryptography 46.0.7.
    # They do not grant access to any repository, database or service.
    monkeypatch.setenv("STACKWISE_ENCRYPTION_KEY", 'AAECAwQFBgcICQoLDA0ODxAREhMUFRYXGBkaGxwdHh8=')
    token = 'gAAAAABlU_EADf8mxgos7aJloSc4ZIFHvJb1FTu3pDZf9a2Eb0SHp5wYkB6vs8MA9u8ssrrQv_v5QUp5IpFlD86fHqrJYitJGoPs1daeLGbC7GFX2Ir-sT75JzCzwGiXYTD_JU9iGIBR'
    assert unseal(token) == "test-only-workspace-connection-token"
